      if (!newDescription.value) return;
      try {
        await taskService.createTask({
          description: newDescription.value
        });
        newDescription.value = '';
        fetchTasks();
      } catch (error) {
        console.error("Erreur lors de la création de la task :", error);
      }
    };
    onMounted(fetchTasks);
    onMounted(async () => {
      try {
        const response = await taskService.getTasks();
        tasks.value = response.data; // met à jour la liste des tâches
      } catch (error) {
        console.error('Erreur lors de la récupération des tâches :', error);
      }
    });
    const toggleStatus = async task => {
      try {
        await taskService.updateTaskStatus(task.id, !task.status);
        fetchTasks();
      } catch (error) {
        console.error('Erreur lors de la mise à jour du status :', error);
      }
    };
    const removeTask = async task => {
      try {
        await taskService.deleteTask(task.id);
        fetchTasks();
      } catch (error) {
        console.error('Erreur lors de la suppression de la task :', error);
      }
    };
    const __returned__ = {
      tasks,
      newDescription,
      fetchTasks,
      createTask,
      toggleStatus,
      removeTask,
      ref,
      onMounted,
      get taskService() {
        return taskService;
      }
    };
